// ===== SMART JOB APPLY V8 + APIFY =====
const existingIds = new Set();
try {
  const idsResp = $('Fetch Existing IDs').first().json;
  const ranges = idsResp.data?.valueRanges || idsResp.valueRanges || [];
  const vals = (ranges[0] || {}).values || [];
  for (const row of vals) { if (row && row[0]) existingIds.add(String(row[0]).trim()); }
} catch(e) {}

const tier1 = ['google','microsoft','amazon','meta','apple','netflix','adobe','salesforce','anthropic','openai','deepmind','cohere','mistral','hugging face','stripe','figma','notion','linear','vercel','cloudflare','twilio','atlassian','databricks','snowflake','palantir','elastic','mongodb','confluent','cockroachdb','supabase','hashicorp','github','gitlab','docker','datadog','grafana','sentry','nvidia','crowdstrike','zscaler','splunk','dynatrace','new relic'];
const tier2 = ['razorpay','phonepe','paytm','cred','groww','upstox','zerodha','smallcase','slice','jupiter','niyo','navi','perfios','setu','juspay','bharatpe','cashfree','zepto','blinkit','swiggy','zomato','flipkart','meesho','nykaa','dunzo','porter','delhivery','shiprocket','bigbasket','reliance','ola','rapido','zoho','freshworks','chargebee','browserstack','postman','hasura','clevertap','darwinbox','keka','mfine','pristyn','healthifyme','curefit','practo','1mg','unacademy','scaler','interviewbit','vedantu','great learning','upgrad','physicswallah','urban company','lenskart','moglix','acko','policybazaar','cars24','spinny','oyo','ixigo','redbus','myntra'];
const tier3 = ['thoughtworks','ltimindtree','mphasis','persistent','coforge','hexaware','qualcomm','intel','amd','arm','samsung','texas instruments','harman','cisco','juniper','vmware','nutanix','palo alto','intuit','autodesk','sap','oracle','ibm','servicenow','workday','zendesk','hubspot','dell','hp','cognizant','infosys','wipro','tcs','hcl','accenture','capgemini','deloitte','kpmg','jpmorgan','jp morgan','goldman sachs','morgan stanley','hsbc','barclays','citibank','visa','mastercard','paypal','walmart','shopify'];

const badTitle = ['unpaid','commission only','mlm','network marketing','direct sales','insurance agent','real estate agent','field sales'];
const badCompany = ['staffing solutions','placement agency','recruitment solutions','manpower','talent hunt','hr consultancy','recruitment firm'];
const skipTitleWords = ['vice president',' vp ','director,','head of engineering','cto ','ceo ','chief technology','chief executive','engineering manager','principal engineer','staff engineer ','distinguished engineer'];
const techKeywords = ['react','node.js','nodejs','python','java','golang','go','rust','typescript','javascript','flutter','android','ios','swift','kotlin','c++','c#','.net','php','ruby','scala','kubernetes','docker','aws','azure','gcp','postgres','mysql','mongodb','redis','kafka','spark','tensorflow','pytorch','llm','ml','ai','data science','spring','django','fastapi','express','nextjs','next.js','vue','angular','nestjs','graphql'];

const rows = [];
const seenThisRun = new Set();

for (const page of $input.all()) {
  const raw = page.json;

  // ===== APIFY JSON PATH =====
  const apifyJobs = Array.isArray(raw) ? raw : (raw && Array.isArray(raw.data)) ? raw.data : null;
  if (apifyJobs) {
    for (const job of apifyJobs) {
      const jobId = String(job.id || '').trim();
      if (!jobId || existingIds.has(jobId) || seenThisRun.has(jobId)) continue;
      seenThisRun.add(jobId);

      const rawTitle = (job.title || '').trim();
      const title = rawTitle.toLowerCase();
      const rawCompany = (job.companyName || '').trim();
      const company = rawCompany.toLowerCase();

      if (!rawTitle || !rawCompany) continue;
      if (badTitle.some(b => title.includes(b))) continue;
      if (badCompany.some(b => company.includes(b))) continue;
      if (skipTitleWords.some(b => title.includes(b))) continue;

      const inT1 = tier1.some(s => company.includes(s));
      const inT2 = !inT1 && tier2.some(s => company.includes(s));
      const inT3 = !inT1 && !inT2 && tier3.some(s => company.includes(s));
      const companyTier = inT1 ? 'Tier1-WorldClass' : inT2 ? 'Tier2-IndianUnicorn' : inT3 ? 'Tier3-GlobalMNC' : 'Tier4-Other';

      const seniority = (job.seniorityLevel || '').toLowerCase();
      let expLevel = 'Entry Level';
      if (seniority.includes('intern') || /intern|trainee|apprentice/.test(title)) expLevel = 'Internship';
      else if (seniority.includes('entry') || /fresher|junior|entry level/.test(title)) expLevel = 'Fresher/0-2yr';
      else if (seniority.includes('mid')) expLevel = '1-3 Years';
      else if (seniority.includes('senior') || /senior|sr\./.test(title)) expLevel = '3-5 Years';

      const desc = (job.descriptionText || '').toLowerCase();
      const foundSkills = techKeywords.filter(k => title.includes(k) || desc.includes(k));
      const reqSkills = foundSkills.length > 0 ? [...new Set(foundSkills)].slice(0,6).join(', ') : 'See Job URL';

      const empType = job.employmentType || 'Full-time';
      const salHint = job.salary || job.salaryInsights || '';
      const location = (job.location || 'India').replace(/\s+/g,' ').trim();
      const jobUrl = job.link || '';
      const postedAt = job.postedAt ? job.postedAt.split('T')[0] : '';
      const hrUrl = 'https://www.linkedin.com/search/results/people/?keywords=Recruiter+Talent+Acquisition+' + encodeURIComponent(rawCompany);
      const now = new Date();

      rows.push([
        now.toISOString().split('T')[0],
        now.toLocaleTimeString('en-IN', {timeZone:'Asia/Kolkata', hour12:false}),
        rawCompany, companyTier, rawTitle, location, jobUrl,
        expLevel, reqSkills, empType, String(salHint), 'Applied',
        hrUrl, 'Apify V8', jobId, postedAt
      ]);
    }
    continue;
  }

  // ===== LINKEDIN HTML PATH =====
  const htmlStr = (raw && typeof raw.data === 'string') ? raw.data :
                  (typeof raw === 'string') ? raw : '';
  if (!htmlStr || htmlStr.length < 500) continue;

  const lis = htmlStr.match(/<li[^>]*>[\s\S]*?<\/li>/g) || [];
  for (const li of lis) {
    const tM = li.match(/class="base-search-card__title"[^>]*>\s*([^<]+)\s*</);
    const cM = li.match(/class="hidden-nested-link"[^>]*>\s*([^<]+)\s*</);
    const uM = li.match(/href="(https?:\/\/[a-z0-9-]+\.linkedin\.com\/jobs\/view\/[^"?]+)/);
    const iM = uM ? uM[1].match(/-(\d+)\/?$/) : null;
    const dM = li.match(/datetime="([^"]+)"/);
    const lM = li.match(/job-search-card__location[^>]*>\s*([^<]+)\s*</);

    if (!tM || !cM || !uM || !iM) continue;
    const jobId = iM[1];
    if (existingIds.has(jobId) || seenThisRun.has(jobId)) continue;
    seenThisRun.add(jobId);

    const rawTitle = tM[1].trim();
    const title = rawTitle.toLowerCase();
    const rawCompany = cM[1].trim().replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>');
    const company = rawCompany.toLowerCase();

    if (badTitle.some(b => title.includes(b))) continue;
    if (badCompany.some(b => company.includes(b))) continue;
    if (skipTitleWords.some(b => title.includes(b))) continue;

    const inT1 = tier1.some(s => company.includes(s));
    const inT2 = !inT1 && tier2.some(s => company.includes(s));
    const inT3 = !inT1 && !inT2 && tier3.some(s => company.includes(s));
    const companyTier = inT1 ? 'Tier1-WorldClass' : inT2 ? 'Tier2-IndianUnicorn' : inT3 ? 'Tier3-GlobalMNC' : 'Tier4-Other';

    const hrUrl = 'https://www.linkedin.com/search/results/people/?keywords=Recruiter+Talent+Acquisition+' + encodeURIComponent(rawCompany);
    let expLevel = 'Entry Level';
    if (/intern|trainee|apprentice/.test(title)) expLevel = 'Internship';
    else if (/fresher|junior|associate|entry level/.test(title)) expLevel = 'Fresher/0-2yr';
    else if (/\b[1-3][-–1-3]\s*(yr|year)/.test(title)) expLevel = '1-3 Years';
    else if (/\b[3-6][-–5-9]\s*(yr|year)/.test(title)) expLevel = '3-5 Years';

    const foundSkills = techKeywords.filter(k => title.includes(k.toLowerCase()));
    const reqSkills = foundSkills.length > 0 ? [...new Set(foundSkills)].join(', ') : 'See Job URL';
    let empType = 'Full-time';
    if (/intern|trainee/.test(title)) empType = 'Internship';
    else if (/contract|freelance/.test(title)) empType = 'Contract';

    const salM = rawTitle.match(/(\d+[\s]*(?:LPA|lpa|lakh|CTC|K\s*pm))/i);
    const location = lM ? lM[1].trim().replace(/\s+/g,' ') : 'India';
    const postedAt = dM ? dM[1].split('T')[0] : '';
    const now = new Date();

    rows.push([
      now.toISOString().split('T')[0],
      now.toLocaleTimeString('en-IN', {timeZone:'Asia/Kolkata', hour12:false}),
      rawCompany, companyTier, rawTitle, location, uM[1],
      expLevel, reqSkills, empType, salM ? salM[1] : '', 'Applied',
      hrUrl, 'Auto V8', jobId, postedAt
    ]);
  }
}

return [{json: {
  status: rows.length > 0 ? 'ready' : 'no_new_jobs',
  new_count: rows.length,
  skipped_duplicates: existingIds.size,
  rows: rows
}}];
